Add three more validators in `validators_later.py`, in the same form as the ones in `validators.py`:

- V7 (`entries`): every warehouse's capacity was respected across runs. Each entry: `{"wh": str, "capacity": int, "max_units": int}`.
- V8 (`entries`): all expiries were notified. Each entry: `{"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}`.
- V9 (`entries`): every supplier's reliability stayed in range. Each entry: `{"supplier": str, "reliability": int}`.

## Repository files

`CONTRIBUTING.md`:

```
# Contributing

- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
```

`validators.py`:

```
"""Validators over depot run outputs.

Each validator vN(items) returns (passed, measured), where `measured` is the
list of failing items (empty when passed). Validators never mutate their input.
"""

# Notification types named in the spec as things the depot emits.
# Source: C14 (REORDER), C13 (EXPIRY), C22 (AUDIT_MISMATCH),
# C17 (SUPPLIER_SUSPENDED), C20 (OVERDRAWN).
REQUIRED_NOTIFICATION_TYPES = (
    "REORDER",
    "EXPIRY",
    "AUDIT_MISMATCH",
    "SUPPLIER_SUSPENDED",
    "OVERDRAWN",
)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def v1(items):
    """V1: every report row satisfies value_cents == units * unit_cost."""
    bad = []
    for row in items:
        try:
            units = row["units"]
            cost = row["unit_cost"]
            value = row["value_cents"]
            if not (_is_int(units) and _is_int(cost) and _is_int(value)):
                raise TypeError("non-int field")
            ok = value == units * cost
        except (KeyError, TypeError):
            ok = False
        if not ok:
            ident = (row.get("sku"), row.get("wh")) if isinstance(row, dict) else row
            bad.append(ident)
    return (len(bad) == 0, bad)


def v2(items):
    """V2: every required notification type was seen in at least one run.

    `items` is a collection of runs; each run is a list of notifications,
    and each notification is a tuple whose first element is its type.
    """
    seen = set()
    for run in items:
        for note in run:
            if isinstance(note, (tuple, list)) and len(note) > 0:
                seen.add(note[0])
    missing = [t for t in REQUIRED_NOTIFICATION_TYPES if t not in seen]
    return (len(missing) == 0, missing)


def v3(items):
    """V3: for each pair, runs with the same seed are identical (a == b).

    Returns the list of seeds whose two runs differ.
    """
    bad = []
    for pair in items:
        if pair["a"] != pair["b"]:
            bad.append(pair["seed"])
    return (len(bad) == 0, bad)


def v4(items):
    """V4: storage cost stayed within budget each day.

    Returns the list of day numbers where storage_cost_cents > budget_cents.
    """
    bad = []
    for day in items:
        if day["storage_cost_cents"] > day["budget_cents"]:
            bad.append(day["day"])
    return (len(bad) == 0, bad)


def v5(items):
    """V5: every clause has at least one test.

    A test counts only if it is a non-empty string.
    Returns the list of clause_ids with no usable test.
    """
    bad = []
    for entry in items:
        tests = entry.get("tests") or []
        usable = [t for t in tests if isinstance(t, str) and t.strip()]
        if not usable:
            bad.append(entry.get("clause_id"))
    return (len(bad) == 0, bad)


def v6(items):
    """V6: two implementations agree on every compared pair (a == b).

    Returns the list of keys where the results disagree.
    """
    bad = []
    for pair in items:
        if pair["a"] != pair["b"]:
            bad.append(pair["key"])
    return (len(bad) == 0, bad)
